CREATE TABLE IF NOT EXISTS "fraud_rules" ("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"description" TEXT NOT NULL,"condition_json" JSONB NOT NULL,"weight" INTEGER NOT NULL,"severity" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"auto_create_case" BOOLEAN NOT NULL DEFAULT true,"auto_hold_payout" BOOLEAN NOT NULL DEFAULT false,"notify_admin" BOOLEAN NOT NULL DEFAULT true,"cooldown_minutes" INTEGER NOT NULL DEFAULT 60,"trigger_count" INTEGER NOT NULL DEFAULT 0,"last_triggered_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "fraud_rules_name_key" ON "fraud_rules"("name"); CREATE INDEX IF NOT EXISTS "fraud_rules_enabled_category_idx" ON "fraud_rules"("enabled","category");
CREATE TABLE IF NOT EXISTS "fraud_alerts" ("id" SERIAL PRIMARY KEY,"category" TEXT NOT NULL,"severity" TEXT NOT NULL,"risk_score" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'new',"entity_type" TEXT NOT NULL,"entity_id" TEXT NOT NULL,"user_id" INTEGER,"rule_id" INTEGER,"confidence" DECIMAL(5,2),"summary" TEXT NOT NULL,"detected_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"assigned_admin_id" INTEGER,"resolved_at" TIMESTAMP(3),"resolution" TEXT);
CREATE INDEX IF NOT EXISTS "fraud_alerts_status_severity_detected_at_idx" ON "fraud_alerts"("status","severity","detected_at"); CREATE INDEX IF NOT EXISTS "fraud_alerts_user_id_status_idx" ON "fraud_alerts"("user_id","status"); CREATE INDEX IF NOT EXISTS "fraud_alerts_entity_type_entity_id_idx" ON "fraud_alerts"("entity_type","entity_id"); CREATE INDEX IF NOT EXISTS "fraud_alerts_rule_id_detected_at_idx" ON "fraud_alerts"("rule_id","detected_at");
CREATE TABLE IF NOT EXISTS "fraud_signals" ("id" SERIAL PRIMARY KEY,"alert_id" INTEGER NOT NULL,"signal_type" TEXT NOT NULL,"weight" INTEGER NOT NULL,"confidence" DECIMAL(5,2),"source" TEXT NOT NULL,"evidence_json" JSONB,"entity_type" TEXT,"entity_id" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "fraud_signals_alert_id_fkey" FOREIGN KEY ("alert_id") REFERENCES "fraud_alerts"("id") ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS "fraud_signals_alert_id_created_at_idx" ON "fraud_signals"("alert_id","created_at");
CREATE TABLE IF NOT EXISTS "fraud_cases" ("id" SERIAL PRIMARY KEY,"primary_alert_id" INTEGER NOT NULL,"case_number" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'new',"severity" TEXT NOT NULL,"risk_score" INTEGER NOT NULL,"assigned_admin_id" INTEGER,"user_id" INTEGER,"opened_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"closed_at" TIMESTAMP(3),"resolution_type" TEXT,"resolution_note" TEXT,CONSTRAINT "fraud_cases_primary_alert_id_fkey" FOREIGN KEY ("primary_alert_id") REFERENCES "fraud_alerts"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX IF NOT EXISTS "fraud_cases_primary_alert_id_key" ON "fraud_cases"("primary_alert_id"); CREATE UNIQUE INDEX IF NOT EXISTS "fraud_cases_case_number_key" ON "fraud_cases"("case_number"); CREATE INDEX IF NOT EXISTS "fraud_cases_status_severity_opened_at_idx" ON "fraud_cases"("status","severity","opened_at"); CREATE INDEX IF NOT EXISTS "fraud_cases_user_id_status_idx" ON "fraud_cases"("user_id","status"); CREATE INDEX IF NOT EXISTS "fraud_cases_assigned_admin_id_status_idx" ON "fraud_cases"("assigned_admin_id","status");
CREATE TABLE IF NOT EXISTS "fraud_evidence" ("id" SERIAL PRIMARY KEY,"case_id" INTEGER NOT NULL,"type" TEXT NOT NULL,"source" TEXT NOT NULL,"file_asset_id" INTEGER,"data_json" JSONB,"added_by_admin_id" INTEGER NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "fraud_evidence_case_id_fkey" FOREIGN KEY ("case_id") REFERENCES "fraud_cases"("id") ON DELETE RESTRICT); CREATE INDEX IF NOT EXISTS "fraud_evidence_case_id_created_at_idx" ON "fraud_evidence"("case_id","created_at");
CREATE TABLE IF NOT EXISTS "fraud_case_notes" ("id" SERIAL PRIMARY KEY,"case_id" INTEGER NOT NULL,"admin_id" INTEGER NOT NULL,"note" TEXT NOT NULL,"visibility" TEXT NOT NULL DEFAULT 'internal',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "fraud_case_notes_case_id_fkey" FOREIGN KEY ("case_id") REFERENCES "fraud_cases"("id") ON DELETE RESTRICT); CREATE INDEX IF NOT EXISTS "fraud_case_notes_case_id_created_at_idx" ON "fraud_case_notes"("case_id","created_at");
CREATE TABLE IF NOT EXISTS "fraud_entity_links" ("id" SERIAL PRIMARY KEY,"case_id" INTEGER NOT NULL,"source_entity_type" TEXT NOT NULL,"source_entity_id" TEXT NOT NULL,"target_entity_type" TEXT NOT NULL,"target_entity_id" TEXT NOT NULL,"link_type" TEXT NOT NULL,"confidence" DECIMAL(5,2),"reason" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "fraud_entity_links_case_id_fkey" FOREIGN KEY ("case_id") REFERENCES "fraud_cases"("id") ON DELETE RESTRICT); CREATE INDEX IF NOT EXISTS "fraud_entity_links_case_id_created_at_idx" ON "fraud_entity_links"("case_id","created_at");
INSERT INTO "admin_permissions" ("key","description") VALUES ('fraud.read','View fraud alerts and cases'),('fraud.manage','Investigate and update fraud cases'),('fraud.rules','Configure fraud scoring rules') ON CONFLICT ("key") DO NOTHING;
INSERT INTO "admin_role_permissions" ("role_id","permission_id") SELECT r."id",p."id" FROM "admin_roles" r CROSS JOIN "admin_permissions" p WHERE r."key"='super_admin' AND p."key" IN ('fraud.read','fraud.manage','fraud.rules') ON CONFLICT DO NOTHING;
